pub const TOKENS_PER_WORD: f64 = 1.15;
pub const TOK_PER_SIZE: f64 = 0.82;

const N: usize = 624;
const M: usize = 397;
const MATRIX_A: u32 = 0x9908_b0df;
const UPPER_MASK: u32 = 0x8000_0000;
const LOWER_MASK: u32 = 0x7fff_ffff;

/// CPython 3.x compatible Mersenne Twister (`random.Random`).
#[derive(Clone)]
pub struct PyMt19937 {
    mt: [u32; N],
    index: usize,
}

impl PyMt19937 {
    pub fn from_u64(seed: u64) -> Self {
        let key: Vec<u32> = if seed == 0 {
            vec![0]
        } else if seed <= u32::MAX as u64 {
            vec![seed as u32]
        } else {
            vec![seed as u32, (seed >> 32) as u32]
        };
        Self::init_by_array(&key)
    }

    pub fn from_i64(seed: i64) -> Self {
        Self::from_u64(seed.unsigned_abs())
    }

    /// Matches CPython 3.x `random.Random(str_seed)` (version=2):
    /// `a = int.from_bytes(a_bytes + sha512(a_bytes).digest(), 'big')`.
    #[allow(clippy::should_implement_trait)]
    pub fn from_str(seed: &str) -> Self {
        let bytes = seed.as_bytes();
        let mut hasher = Sha512::new();
        hasher.update(bytes);
        let digest = hasher.finalize();

        let mut combined = Vec::with_capacity(bytes.len() + digest.len());
        combined.extend_from_slice(bytes);
        combined.extend_from_slice(&digest);

        // Strip leading zero bytes (matches Python int magnitude)
        let first_nz = combined.iter().position(|&b| b != 0);
        let key: Vec<u32> = match first_nz {
            None => vec![0],
            Some(start) => {
                let mag = &combined[start..];
                let mut words = Vec::with_capacity(mag.len().div_ceil(4));
                let mut end = mag.len();
                while end > 0 {
                    let lo = end.saturating_sub(4);
                    let mut w: u32 = 0;
                    for &b in &mag[lo..end] {
                        w = (w << 8) | (b as u32);
                    }
                    words.push(w);
                    end = lo;
                }
                words
            }
        };
        Self::init_by_array(&key)
    }

    fn init_genrand(s: u32) -> Self {
        let mut mt = [0u32; N];
        mt[0] = s;
        for i in 1..N {
            mt[i] = 1_812_433_253u32
                .wrapping_mul(mt[i - 1] ^ (mt[i - 1] >> 30))
                .wrapping_add(i as u32);
        }
        Self { mt, index: N }
    }

    fn init_by_array(init_key: &[u32]) -> Self {
        let mut rng = Self::init_genrand(19_650_218);
        let key_length = init_key.len();
        let mut i: usize = 1;
        let mut j: usize = 0;
        let mut k = N.max(key_length);
        while k > 0 {
            rng.mt[i] = (rng.mt[i]
                ^ ((rng.mt[i - 1] ^ (rng.mt[i - 1] >> 30)).wrapping_mul(1_664_525)))
            .wrapping_add(init_key[j])
            .wrapping_add(j as u32);
            i += 1;
            j += 1;
            if i >= N {
                rng.mt[0] = rng.mt[N - 1];
                i = 1;
            }
            if j >= key_length {
                j = 0;
            }
            k -= 1;
        }
        for _ in 0..(N - 1) {
            rng.mt[i] = (rng.mt[i]
                ^ ((rng.mt[i - 1] ^ (rng.mt[i - 1] >> 30)).wrapping_mul(1_566_083_941)))
            .wrapping_sub(i as u32);
            i += 1;
            if i >= N {
                rng.mt[0] = rng.mt[N - 1];
                i = 1;
            }
        }
        rng.mt[0] = 0x8000_0000;
        rng
    }

    #[inline]
    pub fn next_u32(&mut self) -> u32 {
        if self.index >= N {
            self.twist();
        }
        let mut y = self.mt[self.index];
        self.index += 1;
        y ^= y >> 11;
        y ^= (y << 7) & 0x9d2c_5680;
        y ^= (y << 15) & 0xefc6_0000;
        y ^= y >> 18;
        y
    }

    fn twist(&mut self) {
        const MAG01: [u32; 2] = [0, MATRIX_A];
        for kk in 0..(N - M) {
            let y = (self.mt[kk] & UPPER_MASK) | (self.mt[kk + 1] & LOWER_MASK);
            self.mt[kk] = self.mt[kk + M] ^ (y >> 1) ^ MAG01[(y & 1) as usize];
        }
        for kk in (N - M)..(N - 1) {
            let y = (self.mt[kk] & UPPER_MASK) | (self.mt[kk + 1] & LOWER_MASK);
            self.mt[kk] = self.mt[kk + M - N] ^ (y >> 1) ^ MAG01[(y & 1) as usize];
        }
        let y = (self.mt[N - 1] & UPPER_MASK) | (self.mt[0] & LOWER_MASK);
        self.mt[N - 1] = self.mt[M - 1] ^ (y >> 1) ^ MAG01[(y & 1) as usize];
        self.index = 0;
    }

    #[inline]
    pub fn getrandbits(&mut self, k: u32) -> u32 {
        debug_assert!((1..=32).contains(&k));
        self.next_u32() >> (32 - k)
    }

    #[inline]
    pub fn randbelow(&mut self, n: usize) -> usize {
        debug_assert!(n > 0);
        if n == 1 {
            return 0;
        }
        let k = (usize::BITS - n.leading_zeros()).max(1);
        loop {
            let r = self.getrandbits(k) as usize;
            if r < n {
                return r;
            }
        }
    }

    #[inline]
    pub fn randint(&mut self, a: usize, b: usize) -> usize {
        a + self.randbelow(b - a + 1)
    }

    #[inline]
    pub fn choice<'a, T>(&mut self, slice: &'a [T]) -> &'a T {
        let idx = self.randbelow(slice.len());
        &slice[idx]
    }
}

/// Matches `tools/bench.py:prose(size, seed)` and `tools/client.py:prose(tokens, seed)`.
pub fn prose_with_rng(size: usize, rng: &mut PyMt19937) -> String {
    let target = (size as f64) * 0.72;
    let est_words = (target as usize).saturating_add(16);
    let mut out = String::with_capacity(est_words * 7);
    let mut count: usize = 0;
    while (count as f64) < target {
        let sent_len = rng.randint(6, 16);
        for i in 0..sent_len {
            if count > 0 {
                out.push(' ');
            }
            out.push_str(rng.choice(WORDS));
            if i + 1 == sent_len {
                out.push('.');
            }
            count += 1;
        }
    }
    out
}

pub fn prose_str_seed(size: usize, seed: &str) -> String {
    let mut rng = PyMt19937::from_str(seed);
    prose_with_rng(size, &mut rng)
}

pub fn prose_int_seed(size: usize, seed: i64) -> String {
    let mut rng = PyMt19937::from_i64(seed);
    prose_with_rng(size, &mut rng)
}

pub fn words_for(tokens: usize) -> usize {
    ((tokens as f64 / TOKENS_PER_WORD) as usize).max(1)
}

struct WordStream {
    rng: PyMt19937,
    /// Pre-formatted word indices: index into WORDS plus bit 0x8000 for trailing period.
    units: Vec<u16>,
}

fn word_cache() -> &'static Mutex<HashMap<i64, WordStream>> {
    static CACHE: OnceLock<Mutex<HashMap<i64, WordStream>>> = OnceLock::new();
    CACHE.get_or_init(|| Mutex::new(HashMap::new()))
}

/// Prefix-stable word generator matching `tools/exact.py:words(n, seed)` and `tools/checklib.py:words(n, seed)`.
pub fn words(n: usize, seed: i64) -> String {
    if n == 0 {
        return String::new();
    }
    let mut cache = word_cache().lock().unwrap();
    let entry = cache.entry(seed).or_insert_with(|| WordStream {
        rng: PyMt19937::from_i64(seed),
        units: Vec::with_capacity(n),
    });
    while entry.units.len() < n {
        let k = entry.rng.randint(6, 16);
        for i in 0..k {
            let idx = entry.rng.randbelow(WORDS.len()) as u16;
            let code = if i + 1 == k { idx | 0x8000 } else { idx };
            entry.units.push(code);
        }
    }
    let mut out = String::with_capacity(n * 7);
    for (i, &code) in entry.units[..n].iter().enumerate() {
        if i > 0 {
            out.push(' ');
        }
        out.push_str(WORDS[(code & 0x7FFF) as usize]);
        if (code & 0x8000) != 0 {
            out.push('.');
        }
    }
    out
}

/// Uncached fresh `words()` for benchmarking or single-shot use.
pub fn words_uncached(n: usize, seed: i64) -> String {
    if n == 0 {
        return String::new();
    }
    let mut rng = PyMt19937::from_i64(seed);
    let mut out = String::with_capacity(n * 7);
    let mut count = 0usize;
    while count < n {
        let k = rng.randint(6, 16);
        for i in 0..k {
            let w = rng.choice(WORDS);
            if count < n {
                if count > 0 {
                    out.push(' ');
                }
                out.push_str(w);
                if i + 1 == k {
                    out.push('.');
                }
            }
            count += 1;
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::sha256_hex;

    #[test]
    fn test_prose_matches_python_golden_sha256() {
        let int_cases = [
            (
                0,
                "e37e81c743c11ffe2ce46a37f622223c9210d55b9edacc8a4df2f2e215249a8d",
            ),
            (
                1,
                "f954c80e19d2dcef09d0e3988311fe9e49895ef306d7dd6593600d4bbba6d362",
            ),
            (
                7,
                "568b27f050176330055a0305dd725bfa6833dbc8d1a8da8023df1e08dc54b4fc",
            ),
            (
                42,
                "210e1c2b6791a65d9e2d687101649e824429033cb105d3851b60e07134541ba2",
            ),
            (
                777,
                "e1819ed4ab2981145a2b303626a815a38ae6ca4fb4724ce68d1c1d962987d180",
            ),
            (
                1234,
                "e35f42560eaa194795fa78dd221398e03ab543ffe6d16fdc87d9380d8099ddd8",
            ),
        ];
        for (seed, want) in int_cases {
            let got = sha256_hex(prose_int_seed(200, seed).as_bytes());
            assert_eq!(got, want, "prose int seed {seed}");
        }

        let str_cases = [
            (
                "1234-p-2048-0-deadbeef",
                "834516183af0ff3f7787ee82097ff1817c72619cbb97092237f18ab5376a5a39",
            ),
            (
                "1234-n-8000-cafebabe",
                "1d89948afa930920dd8400e0aedc9c02989ae18a8f7dd08318571a9a709cd5a7",
            ),
        ];
        for (seed, want) in str_cases {
            let got = sha256_hex(prose_str_seed(200, seed).as_bytes());
            assert_eq!(got, want, "prose str seed {seed}");
        }

        let mut prose_ms = Vec::new();
        let mut big_sha = String::new();
        for _ in 0..3 {
            let t0 = std::time::Instant::now();
            let big = prose_str_seed(
                (262144.0 / TOK_PER_SIZE) as usize,
                "1234-p-262144-0-deadbeef",
            );
            prose_ms.push(t0.elapsed().as_secs_f64() * 1000.0);
            big_sha = sha256_hex(big.as_bytes());
        }
        prose_ms.sort_by(|a, b| a.total_cmp(b));
        println!("BENCH prose_256k_ms={:.3}", prose_ms[1]);
        assert_eq!(
            big_sha,
            "ee07b853e2fb0111b82d003715e40d3ec0a00bbc78a8ebe4d21cbcfd3c58ec81"
        );
    }

    #[test]
    fn test_words_matches_python_golden_sha256() {
        let cases = [
            (
                1,
                "a73fe3fecd422d92ea6cb04e5fcdba1f39e129bb4783afa85d418175b65e0bf2",
            ),
            (
                1234,
                "7934fb6b833adcb922adbfd792313bfa260d5b6bc128973c5c649fe720190298",
            ),
            (
                1299,
                "f52997ae1a5d01700e1e6d106d78c377bcc7700bb5a6ceef6ad32b3deca289ad",
            ),
            (
                9141,
                "07ce16bc4f069c0b0d81054212bf7a90c135fb4622febad29ff248b277213cdb",
            ),
        ];
        for (seed, want) in cases {
            let got = sha256_hex(words(200, seed).as_bytes());
            assert_eq!(got, want, "words seed {seed}");
            let got_u = sha256_hex(words_uncached(200, seed).as_bytes());
            assert_eq!(got_u, want, "words_uncached seed {seed}");
        }
        let mut words_ms = Vec::new();
        let mut w_sha = String::new();
        for _ in 0..3 {
            let t0 = std::time::Instant::now();
            let w = words_uncached(200_000, 1234);
            words_ms.push(t0.elapsed().as_secs_f64() * 1000.0);
            w_sha = sha256_hex(w.as_bytes());
        }
        words_ms.sort_by(|a, b| a.total_cmp(b));
        println!("BENCH words_200k_ms={:.3}", words_ms[1]);
        assert_eq!(
            w_sha,
            "db4f9b3948fb1000bc64f8b60030ab65fd85ce45582adf7a5d4822c6462ecbfe"
        );
    }
}
